mustKnow.code:
-- expand: add a new column; old code can still use phone
ALTER TABLE users ADD COLUMN mobile text;
-- migrate: the app writes both columns, then backfills existing data
UPDATE users SET mobile = phone WHERE mobile IS NULL;
-- contract: once every service reads mobile and no longer writes phone
ALTER TABLE users DROP COLUMN phone;

